@pytest.mark.parametrize('name,a,b,f,exp', V, ids=[x[0] for x in V])
def test_speed(name, a, b, f, exp):
    r = speed_check(a, b, f)
    assert {k: r[k] for k in ('winner','a_speed','b_speed','tied')} == exp
def test_default_field():
    assert speed_check({'id':'garchomp'}, {'id':'heatran'})['winner'] == 'a'
